function norm(d){const o={apps:[],finds:[],chk:{},log:[]};if(!d||!Array.isArray(d.apps))return o;
 for(const a of d.apps.slice(0,200)){const A={id:idOf(a),name:clean(a.name,80),subs:[]};if(!A.name)continue;
  for(const s of (Array.isArray(a.subs)?a.subs:[]).slice(0,500)){const B={id:idOf(s),name:clean(s.name,253),funcs:[]};if(!B.name)continue;
   for(const f of (Array.isArray(s.funcs)?s.funcs:[]).slice(0,2000)){const p=clean(f.path,200);if(!p)continue;B.funcs.push({id:idOf(f),method:M.includes(f.method)?f.method:'GET',path:p,status:ST.includes(f.status)?f.status:'untested',note:clean(f.note,300)})}
   A.subs.push(B)}o.apps.push(A)}
 for(const f of (Array.isArray(d.finds)?d.finds:[]).slice(0,5000)){const t=clean(f.title,120);if(t)o.finds.push({id:idOf(f),fn:clean(f.fn,64),app:clean(f.app,80),title:t,sev:SEV.includes(f.sev)?f.sev:'Info',cat:OW.includes(f.cat)?f.cat:OW[0]})}

 const cs=d.chk&&typeof d.chk==='object'?d.chk:{};
 for(const a of o.apps){const src=cs[a.id];if(!src||typeof src!=='object')continue;const r={};for(const k in src)if(/^\d{1,3}\.\d{1,4}$/.test(k)&&src[k]===true)r[k]=true;o.chk[a.id]=r}
 o.log=(Array.isArray(d.log)?d.log:[]).slice(-500).map(x=>({t:Number(x&&x.t)||0,m:clean(x&&x.m,200)})).filter(x=>x.m);
 return o}

